'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var uniform = require( '@stdlib/random/array/uniform' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var pow = require( '@stdlib/math/base/special/pow' );
var floor = require( '@stdlib/math/base/special/floor' );
var Complex128Array = require( '@stdlib/array/complex128' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var ztpsv = require( './../lib/ndarray.js' );


// VARIABLES //

var options = {
	'dtype': 'float64'
};


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {PositiveInteger} N - array length
* @returns {Function} benchmark function
*/
function createBenchmark( N ) {
	var APbuf;
	var xbuf;
	var AP;
	var x;

	xbuf = uniform( N*2, -100.0, 100.0, options );
	x = new Complex128Array( xbuf.buffer );
	APbuf = uniform( (N*(N+1)/2)*2, -100.0, 100.0, options );
	AP = new Complex128Array( APbuf.buffer );

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var i;
		var z;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			z = ztpsv( 'row-major', 'lower', 'no-transpose', 'non-unit', N, AP, 1, 0, x, 1, 0 );
			if ( isnanf( z[ i%z.length ] ) ) {
				b.fail( 'should not return NaN' );
			}
		}
		b.toc();
		if ( isnanf( z[ i%z.length ] ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var min;
	var max;
	var len;
	var f;
	var i;

	min = 1; // 10^min
	max = 6; // 10^max

	for ( i = min; i <= max; i++ ) {
		len = floor( pow( pow( 10, i ), 1.0/2.0 ) );
		f = createBenchmark( len );
		bench( format( '%s:ndarray:size=%d', pkg, (len*(len+1)/2)), f );
	}
}

main();
